async function main() {
  const { PrismaClient } = require("@st-michael/database");
  const prisma = new PrismaClient();
  try {
    const deals = await prisma.registryDeal.findMany({
      select: { id: true, contractNumber: true, project: true, commissionAmountFact: true },
    });
    const byKey = new Map();
    for (const d of deals) {
      const k = `${d.project}|${key(d.contractNumber)}`;
      if (!byKey.has(k)) byKey.set(k, d);
    }

    const stat = { всего: ROWS.length, нашлось: 0, неНашлось: 0, обновлено: 0, ошибок: 0,
                   сСуммой: 0, сВыплатой: 0, сИсточником: 0, красных: 0 };
    const misses = [];
    const updates = [];
    for (const r of ROWS) {
      const project = PROJECT[r.p];
      const hit = project ? byKey.get(`${project}|${key(r.k)}`) : null;
      if (!hit) { stat.неНашлось++; if (misses.length < 8) misses.push(`${r.p} ${r.k}`); continue; }
      stat.нашлось++;
      if (r.red) stat.красных++;
      const parsed = parsePaid(r.paid);
      if (r.amt !== null && r.amt !== undefined && r.amt !== "") stat.сСуммой++;
      if (parsed.paid !== null) stat.сВыплатой++;
      if (r.src) stat.сИсточником++;
      updates.push({
        id: hit.id,
        data: {
          commissionAmountFact: r.amt === null || r.amt === undefined || r.amt === "" ? null : String(r.amt),
          commissionPercentRaw: r.pct === null || r.pct === undefined ? null : String(r.pct),
          commissionPaidRaw: r.paid === null || r.paid === undefined ? null : String(r.paid),
          commissionPaidAmount: parsed.amount === null ? null : String(parsed.amount),
          commissionSheetAt: new Date(SHEET_AT),
          leadSourceRaw: r.src || null,
        },
      });
    }

    console.log("=== Факт комиссии из листа ===");
    for (const [k2, v] of Object.entries(stat)) if (k2 !== "обновлено" && k2 !== "ошибок") console.log(`  ${k2.padEnd(12)} ${v}`);
    if (misses.length) console.log("  примеры несопоставленных:", misses.join(" | "));

    if (!WRITE) { console.log("\nПРОГОН БЕЗ ЗАПИСИ (нужны DRY_RUN=0 и CONFIRM=1)."); return; }
    for (const u of updates) {
      try { await prisma.registryDeal.update({ where: { id: u.id }, data: u.data }); stat.обновлено++; }
      catch (e) { stat.ошибок++; if (stat.ошибок <= 5) console.error("    ", e?.message || e); }
    }
    console.log(`\nЗАПИСЬ ВЫПОЛНЕНА: обновлено ${stat.обновлено}, ошибок ${stat.ошибок}`);
  } finally {
    await prisma.$disconnect();
  }
}
main().catch((e) => { console.error("FATAL:", e?.message || e); process.exit(1); });
